    actor?: null | MacroUserIdStr;
    /**
     * The command's thread announcement, when one was created.
     */
    announcement_message_id?: string | null;
    /**
     * Safe details for clients and downstream consumers.
     */
    failure: CommandFailure;
    /**
     * The session.
     */
