 'ova' | 'ovf' | 'iso' | 'img' | 'swf';

/**
 * Represents a file type update: either set to a specific type or clear to null.
 */
export type FileTypeUpdate = {
    /**
     * Set the file type to a specific value.
     */
    set: FileType;
} | 'clear';

/**
 * A fill specification.
 */
export type FillSpec = {
    kind: 'none';
} | {
    /**
     * Opacity 0-1.
     */
    alpha?: number | null;
    /**
     * `RRGGBB`, or a theme color name (`accent1`, `tx1`, `bg1`...).
     */
    color: string;
    kind: 'solid';
} | {
    /**
     * Angle in degrees.
     */
    angle?: number;
    /**
     * Stop colors (`RRGGBB` or theme names), evenly spaced.
     */
    colors: Array<string>;
    kind: 'gradient';
};

/**
 * A test of one column's cells.
 */
export type FilterCondition = {
    /**
     * The column tested.
     */
    column: string;
    /**
     * What its cell must be. The test's kind must fit the column's type.
     */
    test: FilterTest;
};

/**
 * Conditions joined by one conjunction.
 */
export type FilterGroup = {
    /**
     * The conditions and nested groups. A group without any keeps every
     * row.
     */
    conditions: Array<FilterNode>;
    /**
     * Whether every condition must hold, or any one.
     */
    conjunction: Conjunction;
};

/**
 * One entry of a group: a condition, or a group of its own.
 */
export type FilterNode = (FilterCondition & {
    kind: 'condition';
}) | (FilterGroup & {
    kind: 'group';
});

/**
 * What a column's cell must be, by the kind of value the column holds.
 */
export type FilterTest = {
    kind: 'presence';
    /**
     * Empty, or not.
     */
    operator: PresenceOperator;
} | {
    kind: 'text';
    /**
     * How the cell compares.
     */
    operator: TextOperator;
    /**
     * The text compared against, ignoring case for the containment
     * tests.
     */
    value: string;
} | {
    kind: 'number';
    /**
     * How the cell compares.
     */
    operator: NumberOperator;
    /**
     * The number compared against; finite.
     */
    value: number;
} | {
    kind: 'date';
    /**
     * How the cell compares.
     */
    operator: DateOperator;
    /**
     * The date-time compared against.
     */
    value: string;
} | {
    kind: 'dateRange';
    /**
     * How the cell's range stands to the day.
     */
    operator: DateRangeOperator;
    /**
     * The start of the day compared against.
     */
    value: string;
} | {
    /**
     * Whether the box is checked.
     */
    checked: boolean;
    kind: 'checkbox';
} | {
    kind: 'options';
    /**
     * How the cell's options relate to these.
     */
    operator: SetOperator;
    /**
     * Options of the column; at least one.
     */
    options: Array<string>;
} | {
    /**
     * Entity ids, or for a relation the related rows' ids; at least
     * one.
     */
    entities: Array<string>;
    kind: 'entities';
    /**
     * How the cell's references relate to these.
     */
    operator: SetOperator;
};

/**
 * Which entries to read, and how to order them.
 */
export type FindEntriesRequest = {
    /**
     * Put the largest first.
     */
    descending?: boolean;
    /**
     * Every filter must match.
     */
    filters?: Array<FieldValueInput>;
    /**
     * Most entries to return, 1 to 5000; defaults to 50. Counts and totals
     * cover every match regardless.
     */
    limit?: number | null;
    /**
     * Only entries tracking one of these companies or contacts.
     */
    recordIds?: Array<string>;
    /**
     * Text the record's name, domain or email must contain.
     */
    search?: string | null;
    /**
     * The field to order by; number, date and select fields order by value
     * and stage order.
     */
    sortBy?: string | null;
};

export type FolderItem = {
    fileType?: null | FileType;
    /**
     * The full OS name of the file for deduplication
     */
    fullName: string;
    /**
     * The name of the file, without the extension
     */
    name: string;
    /**
     * The relative path of the file.
     *
     * This is the `webkitRelativePath` with the name of the file stripped at the end.
     */
    relativePath: string;
    /**
     * The sha of the file.
     */
    sha: string;
};

/**
 * Durable progress of an email operation.
 */
export type FollowupState = 'archiving' | 'pending' | 'returning' | 'returned' | 'cancelled' | 'removed';

/**
 * A persisted mapping to an entity owned by an external system.
 */
export type ForeignEntity = {
    /**
     * Timestamp when the record was created.
     */
    createdAt: string;
    /**
     * Identifier assigned by the external system.
     */
    foreignEntityId: string;
    /**
     * Source system that owns the external identifier.
     */
    foreignEntitySource: string;
    /**
     * Internal primary key for this foreign entity record.
     */
    id: string;
    /**
     * Arbitrary metadata stored with the mapping.
     */
    metadata: unknown;
    /**
     * Internal auth entity namespace this foreign entity is stored for.
     */
    storedForAuthEntity: string;
    /**
     * Internal entity identifier this foreign entity is stored for.
     */
    storedForId: string;
    /**
     * Timestamp when the record was last updated.
     */
    updatedAt: string;
};

/**
 * Filters for foreign entity records.
 */
export type ForeignEntityFilters = {
    /**
     * External entity identifiers to filter by. Empty to include all external IDs.
     */
    foreign_entity_ids?: Array<string>;
    /**
     * External source names to filter by. Empty to include all sources.
     */
    foreign_entity_sources?: Array<string>;
    /**
     * Internal foreign entity record IDs to filter by. Empty to include all records.
     */
    ids?: Array<string>;
    /**
     * When true, only return foreign entities whose metadata lists the requesting user as a
     * participant (GitHub `involves:me` semantics for `github_pull_request` records). False or
     * absent applies no filter. Serialized in filter ASTs as the `"me"` literal.
     */
    includes_me?: boolean;
    /**
     * Filter by the notification state of the foreign entity (e.g. whether the requesting user's
     * GitHub PR notification is done/seen).
     */
    notification_filters?: NotificationFilters;
};

/**
 * A form: a view of one database table whose rows are its responses.
 */
export type Form = {
    /**
     * Whether nobody, the owner included, can see who gave which response.
     * Who responded is kept apart from the responses, only so nobody
     * responds twice. Fixed once anyone has responded.
     */
    anonymous: boolean;
    /**
     * Who may respond.
     */
    audience: Audience;
    /**
     * Its logo, cover image and accent color.
     */
    branding: FormBranding;
    /**
     * When it stops taking responses, if it does.
     */
    closesAt: string | null;
    /**
     * What a respondent reads once their response is saved; empty for the
     * default.
     */
    confirmationMessage: string;
    /**
     * When it was created.
     */
    createdAt: string;
    /**
     * The database holding its responses.
     */
    databaseId: string;
    /**
     * What respondents read under the name.
     */
    description: string;
    /**
     * The form.
     */
    id: string;
    /**
     * Whether Drive leaves it, and the database behind it, out of its
     * listings, as for a channel poll.
     */
    isHiddenInDrive: boolean;
    /**
     * Its display name. A standalone form follows the database it created;
     * a form attached to an existing table has its own name.
     */
    name: string;
    /**
     * Its owner.
     */
    ownerId: string;
    /**
     * The folder it is filed in; `null` at the root.
     */
    projectId: string | null;
    /**
     * The person column each signed-in submission names its respondent in;
     * `null` once deleted, and on a form created anonymous. An anonymous
     * form never writes it.
     */
    respondentColumnId: string | null;
    /**
     * Whether people with View may read individual response rows.
     */
    responsesVisible: boolean;
    /**
     * Whether its owner closed it.
     */
    status: FormStatus;
    /**
     * The date column each submission stamps; `null` once deleted.
     */
    submittedColumnId: string | null;
    /**
     * The table whose rows are its responses.
     */
    tableId: string;
    /**
     * Whether respondents may read option tallies.
     */
    tallyVisible: boolean;
    /**
     * When its facts or layout last changed.
     */
    updatedAt: string;
};

/**
 * The caller's level on a form: view responds (and reads responses when
 * they are shared), edit changes questions and reads responses, owner
 * also sets the audience, closes and trashes it.
 */
export type FormAccess = 'view' | 'edit' | 'owner';

/**
 * A form's logo, cover image and accent color, each unset by default.
 */
export type FormBranding = {
    accentColor: null | AccentColor;
    /**
     * The static file shown as a banner across the top of the page.
     */
    coverFileId: string | null;
    /**
     * The static file shown as the logo above the title.
     */
    logoFileId: string | null;
};

/**
 * A ready collaborative form and the result of publishing its latest draft.
 */
export type FormCollaboration = {
    /**
     * The latest validated form. The form id also identifies its surface.
     */
    detail: FormDetail;
    /**
     * Why the current draft cannot yet replace the respondent layout.
     * Only editors can request this result.
     */
    publicationError?: FormPublicationProblem;
};

/**
 * A form with its layout, as the caller may see it.
 */
export type FormDetail = {
    /**
     * The caller's level on it.
     */
    access: FormAccess;
    /**
     * The form's facts.
     */
    form: Form;
    /**
     * Its sections, in order.
     */
    sections: Array<FormSectionDetail>;
    /**
     * Whether its database is in the trash, so it has no table to show or
     * write: its sections keep no questions and it takes no responses.
     */
    tableGone: boolean;
};

/**
 * What went wrong with a forms request.
 */
export type FormErrorCode = 'tableAlreadyHasForm' | 'notFound' | 'forbidden' | 'ownerOnly' | 'signInRequired' | 'closed' | 'tableGone' | 'alreadyResponded' | 'noResponse' | 'anonymousResponseFinal' | 'unknownQuestion' | 'repeatedAnswer' | 'missingAnswer' | 'invalidAnswer' | 'widgetMismatch' | 'fileUploadNeedsSignIn' | 'invalidLayout' | 'invalidName' | 'invalidSharing' | 'tallyHidden' | 'invalidBranding' | 'conflict' | 'internal';

/**
 * Why a forms request was refused or failed.
 */
export type FormErrorResponse = {
    /**
     * What went wrong.
     */
    code: FormErrorCode;
    /**
     * What went wrong, in words.
     */
    message: string;
    problem: null | LayoutProblem;
    /**
     * The question it is about, if one.
     */
    question: string | null;
};

/**
 * Every section of a form, in order.
 */
export type FormLayout = {
    /**
     * The sections, first first.
     */
    sections: Array<FormSection>;
};

/**
 * An editor's saved draft is not yet the version respondents can use.
 */
export type FormPublicationProblem = {
    kind: 'invalidDraft';
} | {
    kind: 'layout';
    /**
     * The invariant the editor needs to repair.
     */
    problem: LayoutProblem;
} | {
    kind: 'widgetMismatch';
    /**
     * The question to repair.
     */
    question: string;
} | {
    kind: 'fileUploadNeedsSignIn';
} | {
    kind: 'pending';
};

/**
 * A question with its column's facts.
 */
export type FormQuestionDetail = {
    /**
     * The column it writes.
     */
    column: string;
    /**
     * What respondents read under the title.
     */
    helpText: string;
    /**
     * The question.
     */
    id: string;
    /**
     * The column's type.
     */
    kind: ColumnKind;
    /**
     * The column's options, in order, for a select or tag column.
     */
    options: Array<QuestionOption>;
    /**
     * Whether a response must answer it.
     */
    required: boolean;
    /**
     * The column's name.
     */
    title: string;
    widget: null | Widget;
};

/**
 * One entry of a form's submission ledger: who answered, when, and where
 * the answers went.
 */
export type FormResponse = {
    /**
     * The form.
     */
    formId: string;
    /**
     * The entry.
     */
    id: string;
    /**
     * The row holding the answers; `null` when stopped, or once the row was
     * deleted from the table.
     */
    row: string | null;
    /**
     * Saved, or stopped at a gate.
     */
    status: ResponseStatus;
    /**
     * The gate that stopped it.
     */
    stoppedAtSection: string | null;
    /**
     * When it was first submitted.
     */
    submittedAt: string;
    /**
     * When it last changed.
     */
    updatedAt: string;
};

/**
 * One section of a layout: questions on one screen, or a gate the answers
 * so far must pass.
 */
export type FormSection = {
    /**
     * What respondents read under the title.
     */
    description: string;
    /**
     * The section, under an id the client mints.
     */
    id: string;
    kind: 'questions';
    /**
     * Its questions, in order.
     */
    questions: Array<QuestionLayout>;
    /**
     * When to show it: the rules answers of earlier shown sections must
     * pass, naming only their columns. A section whose rules fail is
     * skipped: its questions are not required and their answers are
     * not written. Absent, it is always shown.
     */
    showWhen?: FilterGroup;
    /**
     * Its title; may be empty.
     */
    title: string;
} | {
    /**
     * Its description, for editors.
     */
    description: string;
    /**
     * The section, under an id the client mints.
     */
    id: string;
    kind: 'gate';
    /**
     * What a stopped respondent reads.
     */
    message: string;
    /**
     * The rules, naming only columns asked in earlier sections.
     */
    rules: FilterGroup;
    /**
     * Its title, for editors.
     */
    title: string;
} | {
    /**
     * What respondents read before choosing a time.
     */
    description: string;
    /**
     * The section, under an id the client mints.
     */
    id: string;
    kind: 'booking';
    /**
     * The native booking event. Respondent layouts never include this target.
     */
    target: BookingTarget;
    /**
     * Its title.
     */
    title: string;
};

/**
 * One section of a form as it reads.
 */
export type FormSectionDetail = {
    /**
     * Its description.
     */
    description: string;
    /**
     * The section.
     */
    id: string;
    kind: 'questions';
    /**
     * Its questions, in order.
     */
    questions: Array<FormQuestionDetail>;
    /**
     * When to show it, from earlier shown sections' answers; absent,
     * it is always shown. Sent to every caller so a respondent's page
     * can skip it.
     */
    showWhen?: FilterGroup;
    /**
     * Its title.
     */
    title: string;
} | {
    /**
     * Its description.
     */
    description: string;
    /**
     * The section.
     */
    id: string;
    kind: 'gate';
    /**
     * What a stopped respondent reads.
     */
    message: string;
    /**
     * The rules.
     */
    rules: FilterGroup;
    /**
     * Its title.
     */
    title: string;
} | {
    /**
     * Its description.
     */
    description: string;
    /**
     * The section.
     */
    id: string;
    kind: 'booking';
    /**
     * Editors can configure the destination; respondent layouts omit it.
     */
    target?: BookingTarget;
    /**
     * Its title.
     */
    title: string;
};

/**
 * Where a new form's responses go.
 */
export type FormSource = {
    /**
     * Make the form anonymous from the start: its table gets no
     * Respondent column.
     */
    anonymous?: boolean;
    /**
     * Keep the form, and the database made for it, out of Drive, as
     * for a channel poll.
     */
    isHiddenInDrive?: boolean;
    kind: 'new';
} | {
    /**
     * The table's database.
     */
    databaseId: string;
    kind: 'table';
    /**
     * The table.
     */
    tableId: string;
};

/**
 * Whether a form takes responses, as its owner set it. A form also stops
 * taking them once its closing time passes.
 */
export type FormStatus = 'open' | 'closed';

/**
 * How the table's rows answer each choice question.
 */
export type FormTally = {
    /**
     * One tally per select, numeric select, tag or checkbox question, in
     * layout order.
     */
    questions: Array<QuestionTally>;
};

/**
 * An expression over one row's cells.
 */
export type Formula = {
    /**
     * The column placement.
     */
    column: string;
    kind: 'column';
} | {
    kind: 'number';
    /**
     * The value; finite.
     */
    value: number;
} | {
    kind: 'binary';
    /**
     * The left operand.
     */
    left: Formula;
    /**
     * How.
     */
    operator: Operator;
    /**
     * The right operand.
     */
    right: Formula;
} | {
    kind: 'negate';
    /**
     * The expression negated; a number.
     */
    operand: Formula;
};

/**
 * The entries a query matched.
 */
export type FoundEntriesResponse = {
    /**
     * Whether every entry was read; a pipeline beyond 5000 entries is not,
     * so counts and totals cover only the entries read.
     */
    complete: boolean;
    /**
     * Matched entries per option of each single-select field.
     */
    counts: Array<FieldOptionCounts>;
    /**
     * The first `limit` matches, in the requested order.
     */
    entries: Array<PipelineEntry>;
    /**
     * How many entries matched in all.
     */
    matched: number;
    /**
     * The pipeline read, with its fields and version.
     */
    pipeline: PipelineFields;
    /**
     * The sum of each number field over the matched entries.
     */
    totals: Array<FieldTotal>;
};

export type GenericErrorResponse = {
    /**
     * Indicates if an error occurred
     */
    error: boolean;
    /**
     * Message to explain failure
     */
    message: string;
};

